-- Extended interface help, setup wizard and tooltip translations.
local ADDON, ns = ...
local baseTranslate = ns.T
local extra = {
    ["What this addon does"] = "Что делает этот аддон",
    ["Everything is editable later with /mcfmenu (options panel), or /mcf to move/lock frames."] = "Позже всё можно изменить через /mcfmenu (настройки) или перемещать и блокировать рамки через /mcf.",
    ["Bundled profiles for other addons"] = "Встроенные профили других аддонов",
    ["These addons are loaded and ship a bundled Gonkast profile."] = "Эти аддоны загружены; для них доступен профиль Gonkast.",
    ["Recommended: tick them all -- the preset is built around these profiles and won't look as intended without them. Nothing is pre-selected on purpose, so you have to tick them yourself."] = "Рекомендуется отметить все пункты: оформление рассчитано на эти профили. По умолчанию они не выбраны — отметьте нужные вручную.",
    ["Before you do: this overwrites that addon's entire configuration and CANNOT be undone -- not by /mcfundo, not by reinstalling. Back up any layout you care about first."] = "Внимание: это полностью заменит настройки аддона. Отменить замену нельзя — даже через /mcfundo или переустановку. Сначала сохраните важные настройки.",
    ["No supported addons detected (Bartender4, DynamicCam, Masque, Chattynator)."] = "Совместимые аддоны не обнаружены (Bartender4, DynamicCam, Masque, Chattynator).",
    ["Turn any of these on or off now, or change them later from the addon's options panel. Hover each one for details."] = "Включите или выключите параметры сейчас либо измените их позже в настройках аддона. Наведите курсор на пункт, чтобы прочитать подсказку.",
    ["Holding the right mouse button turns the camera AND your character together, like most modern third-person games, instead of Blizzard's default free-camera drag."] = "Удерживайте правую кнопку мыши, чтобы поворачивать камеру и персонажа одновременно — как в современных играх от третьего лица.",
    ["Hides the default Blizzard player/pet/target/target-of-target/boss/party frames and cast bars, since this addon draws its own. Turning this OFF requires a /reload to bring them back."] = "Скрывает стандартные рамки игрока, питомца, цели, цели цели, боссов и группы, а также полосы применения Blizzard. При отключении потребуется /reload.",
    ["Fixes DialogueUI's compatibility with DynamicCam: opening DialogueUI's panel calls a method that freezes DynamicCam's camera and never releases it, breaking its custom camera situations. This neutralizes that call. Only matters if you use BOTH DialogueUI and DynamicCam — and DialogueUI's own \"Camera Movement\" option must be turned OFF for this to work."] = "Исправляет конфликт DialogueUI с DynamicCam: открытие панели DialogueUI замораживает камеру DynamicCam. Исправление нужно, только если установлены оба аддона; в DialogueUI также отключите параметр «Движение камеры».",
    ["The full options panel (Interface Options > AddOns > this addon) has many more settings beyond these 3 — this page only surfaces the ones most people want to decide on day one."] = "В полном меню (Настройки интерфейса > Модификации > этот аддон) есть много других параметров. Здесь собраны три главных настройки для первого запуска.",
    ["Explorer Mode fades out the elements you choose (unit frames, portraits, auras, and more) until you hover where they are -- combat, having a target, or casting can also force them fully visible. It's OFF by default. Turn it on here if you want that minimalist look; you'll pick exactly which elements it manages, and fine-tune the conditions, later from the main options panel (Explorer section)."] = "Режим обзора скрывает выбранные элементы (рамки, портреты, ауры и другое), пока вы не наведёте на них курсор. В бою, при выбранной цели или применении заклинания их можно оставить видимыми. По умолчанию режим выключен. Здесь его можно включить, а затем выбрать элементы и условия в разделе «Обзор» главного меню.",
    ["Nothing is chosen to fade yet -- enabling this alone (or picking a preset above) won't change anything else until you fine-tune it later. All of this stays editable from the main options panel."] = "Пока не выбраны элементы для скрытия. Одно лишь включение режима или выбор профиля выше ничего больше не изменит. Настройки можно будет уточнить в главном меню.",
    ["Applies the Gonkast preset itself. If you ticked any addon on the previous page, this also REPLACES that addon's entire SavedVariables with the bundled profile (Bartender4 bars, DynamicCam, Masque skin, Chattynator chat) — permanently. Ticked nothing? Then only this addon's own preset is applied and nothing else is touched. A manual /reload is required afterwards."] = "Применяет профиль Gonkast. Если на предыдущей странице вы отметили аддоны, их сохранённые настройки будут полностью и безвозвратно заменены встроенными профилями (панели Bartender4, DynamicCam, оформление Masque и чат Chattynator). Если ничего не отмечено, применится только профиль этого аддона. После этого вручную выполните /reload.",
    ["The HUD layout (\"Gonkast Preset\", Bartender4/portrait positions etc) is a separate, MANUAL step: the button above shows a copyable code — paste it yourself via Esc > Edit Mode > Import Layout. Doing it by hand avoids a harmless-but-noisy taint warning that an automatic import always triggered. Also reachable any time later with |cffffff00/mcfhud|r."] = "Раскладка интерфейса (Gonkast Preset, панели Bartender4, положение портретов и другое) импортируется отдельно вручную. Нажмите кнопку выше, скопируйте код и вставьте его через Esc > Режим редактирования > Импорт раскладки. Ручной импорт позволяет избежать предупреждения игры. Позже раскладку можно открыть командой |cffffff00/mcfhud|r.",
    ["Everything is editable later with /mcfmenu (options panel), or /mcf to move/lock frames."] = "Позже всё можно изменить через /mcfmenu или переместить и заблокировать рамки командой /mcf.",
    ["Or jump straight to a preset:"] = "Или сразу выберите профиль:",
    ["Nothing selected to apply."] = "Ничего не выбрано для применения.", ["Type /reload now."] = "Теперь выполните команду /reload.",
    ["Open Options Panel"] = "Открыть настройки", ["Or type /mcfmenu, or click the AddOn Compartment icon (puzzle piece near the minimap)."] = "Введите /mcfmenu или нажмите значок аддонов (пазл рядом с мини-картой).",
    ["Click to open the options panel."] = "Нажмите, чтобы открыть настройки.", ["Shift+click to open the Nameplate Designer."] = "Shift + щелчок — открыть редактор индикаторов.", ["Drag to move this button."] = "Перетащите, чтобы переместить эту кнопку.",
    ["Click a piece to select it (options appear below) — drag to move, scroll to resize. Drag the dark background to reposition this window. /mcfnpdesigner to close."] = "Нажмите на элемент, чтобы выбрать его и открыть настройки ниже. Перетаскивайте для перемещения, прокручивайте колёсико для изменения размера. Перетащите тёмный фон, чтобы передвинуть окно. Команда закрытия: /mcfnpdesigner.",
    ["|cffffe19bNameplate Designer|r"] = "|cffffe19bРедактор индикаторов|r", ["(none selected)"] = "(ничего не выбрано)",
    ["AzeriteUI |cffffcc00—|r Gonkast Preset"] = "AzeriteUI |cffffcc00—|r профиль Gonkast", ["AzeriteUI - Gonkast Preset"] = "AzeriteUI — профиль Gonkast",
    ["Editing:  "] = "Редактирование:  ",
    ["Click = the secure button (right-click menu / targeting). 0 follows the bar size. Applies when preview is OFF."] = "Щелчок проходит к защищённой кнопке (цель или меню правой кнопкой). Значение 0 подстраивается под размер полосы. Работает, когда предпросмотр выключен.",
    ["Detected via combat log only (public API) -- same as Blizzard's own arena frames."] = "Определяется только через журнал боя и публичный API, как стандартными рамками арены Blizzard.",
    ["Long spell names wrap to 2 lines (within the cast bar width). Max characters truncates with '..' (readable names only)."] = "Длинные названия заклинаний переносятся на две строки по ширине полосы. Ограничение символов обрезает слишком длинные названия.",
    ["Reskins GameTooltip and related tooltips (items, units, comparisons) to match this preset."] = "Оформляет подсказки предметов, персонажей и сравнений в стиле этого профиля.",
    ["Fixed texture (same as AzeriteUI). To move it: enter Lock (top bar) — it shows with a draggable outline."] = "Фиксированная текстура как в AzeriteUI. Чтобы переместить её, включите блокировку на верхней панели — появится рамка для перетаскивания.",
    ["If no condition is met, the alternate position is used. Disabling the toggle above always keeps the primary position, regardless of the conditions."] = "Если ни одно условие не выполнено, используется альтернативное положение. Если выключить переключатель выше, всегда будет использоваться основное положение.",
    ["ToT and Party use a class icon (no 3D model or zoom)."] = "Для цели цели и группы используется значок класса без 3D-модели и приближения.",
    ["Shows the raid target icon (skull, cross, star...) as a badge over the party portrait, only when the member is marked. In preview it shows a sample skull."] = "Показывает метку рейда (череп, крест, звезда и т. п.) поверх портрета участника, если он отмечен. В предпросмотре отображается пример с черепом.",
    ["Global font size/color here are the base. Per-text Size/Color/Alpha are in the TEXT tab; the calendar button is in the CAL tab. In preview, drag each element to move it."] = "Здесь задаются базовые размер и цвет шрифта. Размер, цвет и прозрачность отдельных надписей настраиваются во вкладке «Текст», кнопка календаря — во вкладке «Календарь». В предпросмотре перетаскивайте элементы.",
    ["In preview (/mcf): drag the row to move it. Reskins the Blizzard micro buttons (no background). Repositioning applies out of combat."] = "В предпросмотре (/mcf) перетащите ряд, чтобы переместить его. Меняется оформление микрокнопок Blizzard без фона. Перемещение применяется вне боя.",
    ["Controls the world chat bubbles: hides their background and sets the text font/size/outline/color. Applies live as bubbles appear."] = "Настраивает облачка игрового чата: скрывает фон и задаёт шрифт, размер, обводку и цвет текста. Применяется сразу к новым сообщениям.",
    ["The map itself keeps whatever size Blizzard's Edit Mode gives it — this only moves/scales the round frame (border, icons, ring) built around it. Drag in Lock mode to reposition; mouse wheel over it in Lock adjusts scale."] = "Размер самой карты задаётся в режиме редактирования Blizzard. Здесь перемещается и масштабируется только круглая рамка вокруг неё (ободок, значки и кольцо). В режиме блокировки перетащите её или измените масштаб колёсиком.",
    ["Offsets are relative to the minimap's own center (LFG eye), top edge (dismount button), bottom edge (coordinates), or bottom edge again (below-minimap widget)."] = "Смещения отсчитываются от центра мини-карты (значок поиска группы), верхнего края (кнопка спешивания) или нижнего края (координаты и виджет под картой).",
    ["Offsets are relative to the minimap's own center (tracking button) or bottom edge (mail indicator). Both can also be dragged freely while in Lock mode."] = "Смещения отсчитываются от центра мини-карты для кнопки слежения и от нижнего края для значка почты. В режиме блокировки оба элемента можно перетаскивать.",
    ["Leave the path empty to use the addon's default texture. Only the ring's actual fill/progress arc isn't customizable, to keep the XP/Reputation reading intact."] = "Оставьте путь пустым, чтобы использовать стандартную текстуру аддона. Заполнение кольца нельзя изменить, чтобы сохранить отображение опыта и репутации.",
    ["Shows automatically in any raid group and in battlegrounds only. Growth direction, per-row/column limits and spacing live in the Layout tab; the container's own screen position lives in Pos; icon positions live in Icons."] = "Отображается только в рейдовой группе и на полях боя. Направление, число рамок в ряду или столбце и интервалы настраиваются во вкладке «Раскладка»; положение группы — в «Положение», значков — в «Значки».",
    ["These position/size the icons and bar on member #1 in the Lock preview — every other member (real or preview) copies the same values, since all 40 share one style profile. The power bar's width follows the health bar's automatically."] = "Настраивает положение и размер значков и полосы первого участника в предпросмотре блокировки. Остальные участники используют те же значения, поскольку все 40 рамок используют общий профиль. Ширина полосы ресурса подстраивается под полосу здоровья.",
    ["The grid always grows in rows: each row fills horizontally (left or right), and new rows stack either upward or downward. Member size is fixed to match AzeriteUI exactly."] = "Сетка всегда строится рядами: каждый ряд заполняется по горизонтали слева или справа, а новые ряды добавляются вверх или вниз. Размер рамок фиксирован для соответствия AzeriteUI.",
    ["Only the whole grid moves as one in Lock mode — individual members are positioned by the grid itself, not draggable one by one."] = "В режиме блокировки перемещается вся сетка целиком. Отдельные участники размещаются сеткой и не перетаскиваются по одному.",
    ["How far away nameplates render."] = "Дистанция отображения индикаторов противников.",
    ["Off by default. Only changes stacking order -- position/size/color still come from the Nameplate Designer."] = "По умолчанию выключено. Меняет только порядок слоёв; положение, размер и цвет задаются в редакторе индикаторов.",
    ["Native Blizzard nameplate opacity CVars, per state."] = "Стандартная прозрачность индикаторов Blizzard отдельно для каждого состояния.",
    ["Opacity range across the max distance (see General tab)."] = "Диапазон прозрачности на максимальной дистанции (см. вкладку «Общее»).",
    ["Opacity override for your current target vs everything else."] = "Отдельная прозрачность текущей цели относительно остальных.",
    ["Opacity when the plate is behind walls/objects."] = "Прозрачность индикатора за стенами и объектами.",
    ["Only while you have a target selected: plates behind walls/objects vanish instead of using the Occluded alpha above. No target = normal behavior."] = "Работает только при выбранной цели: индикаторы за стенами и объектами скрываются вместо использования прозрачности выше. Без выбранной цели поведение обычное.",
    ["Off: that category keeps Blizzard's native plate untouched. Name only: just the floating name, no bar/cast. Health bar: full custom plate, same as hostiles."] = "«Выкл.» оставляет стандартный индикатор Blizzard без изменений. «Только имя» показывает имя без полосы здоровья и заклинания. «Полоса здоровья» включает полный индикатор, как у противников.",
    ["Friendly players colored by class instead of plain white/green. NPCs and pets unaffected."] = "Имена союзных игроков окрашиваются по классам вместо белого или зелёного цвета. На NPC и питомцев не влияет.",
    ["Switches NPCs/Pets modes above to \"off\" while in a dungeon/raid (native Blizzard plate, unstyled) and restores them on exit. Can't hide/fade the native bar itself -- Blizzard blocks addons from touching it at all. Doesn't apply to friendly players."] = "Выключает оформление NPC и питомцев в подземельях и рейдах, возвращая стандартные индикаторы Blizzard, и восстанавливает его после выхода. Не скрывает стандартные полосы Blizzard. Не применяется к союзным игрокам.",
    ["CVar-only, crash-safe. Doesn't apply to NPCs/pets -- Blizzard blocks addons from hiding parts of their protected instance plates, no workaround exists. Those keep the Players/NPCs/Pets modes above."] = "Используются только безопасные CVar. Не применяется к NPC и питомцам: Blizzard запрещает аддонам скрывать части защищённых индикаторов в подземельях. Для них действуют настройки игроков, NPC и питомцев выше.",
    ["Direction sets the side that stays fixed while the row grows; offsets nudge it from there."] = "Направление задаёт неподвижный край ряда, от которого он растёт. Смещения корректируют положение.",
    ["Snap to other elements' edges and centers while dragging."] = "При перетаскивании привязывать элемент к краям и центрам других элементов.",
    ["Per-unit outline width/height live in each unit's Bar tab. Move/Lock and Copy/Paste stay in the footer. 'Apply addon profiles' sets Bartender4/DynamicCam/Masque/Chattynator profiles."] = "Толщина обводки каждой рамки настраивается во вкладке «Полоса». Перемещение, блокировка, копирование и вставка остаются внизу окна. Кнопка применения профилей задаёт настройки Bartender4, DynamicCam, Masque и Chattynator.",
    ["Enabled elements fade out and reappear when you hover where they are (works even while hidden). See 'Conditions' for always-show rules, opacity, and content-type filters."] = "Включённые элементы исчезают и появляются при наведении в их область, даже если скрыты. Во вкладке «Условия» задаются правила постоянного отображения, прозрачность и типы контента.",
    ["Also treat bonus bars as a replacement."] = "Также считать бонусные панели заменой основной.",
    ["|cffff5555Careful:|r druid forms use bonus bars, so with this on a druid in cat or bear form would have every other bar hidden the whole time. Same for any class with a form or stance that swaps the bar."] = "|cffff5555Внимание:|r формы друида используют бонусные панели. В кошачьей или медвежьей форме это скроет все остальные панели. То же относится к формам и стойкам других классов, переключающим панель.",
    ["Useful if you fly or use a bar-swapping mount and want the rest out of the way."] = "Полезно при полёте или езде на транспорте, переключающем панель команд.",
    ["Housing restores your previous setup on the way out. Bar hiding works whether Explorer is on or off, and mouseover still reveals."] = "При выходе из жилища восстанавливаются прежние настройки. Скрытие панелей работает независимо от режима обзора; наведение мыши показывает их.",
    ["Combat/target/casting force enabled elements fully visible. 'Active in' limits the whole Explorer to the chosen content types."] = "Бой, выбранная цель и применение заклинания показывают включённые элементы полностью. Параметр «Активен в» ограничивает режим выбранными типами контента.",
    ["Applying a profile replaces your current Elements toggles. It never touches Conditions, except Combat also enables 'Always show in combat'."] = "Применение профиля заменяет текущие переключатели элементов. Условия не меняются; профиль «Бой» также включает «Всегда показывать в бою».",
    ["Applies to ALL 5 party frames at once. Debuffs and buffs are separate groups "] = "Применяется сразу ко всем пяти рамкам группы. Ослабления и усиления находятся в отдельных группах ",
    ["Applies to ALL 6 arena frames at once (allies + enemies). Debuffs and buffs "] = "Применяется сразу ко всем шести рамкам арены (союзники и противники). Ослабления и усиления ",
    ["Shows auras on your focus target on mouseover, or fixed while you're in "] = "Показывает ауры цели фокуса при наведении или постоянно, когда вы находитесь в ",
    ["Shows your own auras -- always visible. Debuffs and buffs are separate "] = "Показывает ваши ауры постоянно. Ослабления и усиления находятся в отдельных группах ",
    ["Shows auras on your target -- always visible while targeting. Debuffs and "] = "Показывает ауры выбранной цели постоянно. Ослабления и усиления ",
    ["Combo points, Holy Power, Chi, Soul Shards, Arcane Charges, Essence — auto-detects your class/spec's resource. Same layout and textures as AzeriteUI. Runes (Death Knight), Stagger (Brewmaster) and Soul Fragments (Demon Hunter) aren't supported yet. Try /mcfclasspowerdiag to check detection live."] = "Комбо-очки, сила Света, ци, осколки душ, чародейские заряды и сущность определяются по классу и специализации. Используются раскладка и текстуры AzeriteUI. Руны рыцаря смерти, пошатывание хмелевара и осколки душ охотника на демонов пока не поддерживаются. Команда /mcfclasspowerdiag показывает работу определения.",
    ["Detected: (none of the supported addons are loaded)"] = "Обнаружено: совместимые аддоны не загружены", ["Detected: "] = "Обнаружено: ", ["From: "] = "Источник: ", ["Growth: "] = "Направление роста: ",
    ["Step "] = "Шаг ", ["Show:"] = "Показать:", ["New preset name"] = "Название нового профиля", ["Choose texture"] = "Выберите текстуру", ["Expand / collapse all groups"] = "Развернуть или свернуть все группы",
    ["Mouselook (right-click drag)"] = "Свободный обзор (удерживайте правую кнопку мыши)", ["Hide Blizzard unit frames"] = "Скрыть стандартные рамки Blizzard", ["DynamicCam camera fix"] = "Исправление камеры DynamicCam",
    ["Ctrl+A y Ctrl+C para copiar"] = "Нажмите Ctrl+A, затем Ctrl+C, чтобы скопировать", ["Ctrl+A  y luego  Ctrl+C  para copiar"] = "Нажмите Ctrl+A, затем Ctrl+C, чтобы скопировать", ["Ctrl+A  y luego  Ctrl+C  para copiar y pasarselo a Claude"] = "Нажмите Ctrl+A, затем Ctrl+C, чтобы скопировать и отправить в Claude",
