}
for key, value in pairs(extra) do
    if key:find("recommended", 1, true) then
        -- Keep Blizzard's color escape sequence while translating the label.
        local label = key:gsub("  |cffd6b896%(recommended%)|r", "")
        local translated = extra[label] or baseTranslate(label)
        extra[key] = translated .. "  |cffd6b896(рекомендуется)|r"
    end
end
ns.T = function(text)
    if type(text) ~= "string" or GetLocale() ~= "ruRU" then return baseTranslate(text) end
    if type(text) == "string" then
        local base, suffix = text:match("^(.-)(  |cffd6b896%(recommended%)|r)$")
        if base then return (extra[base] or baseTranslate(base)) .. "  |cffd6b896(рекомендуется)|r" end
        if extra[text] then return extra[text] end
    end
    return baseTranslate(text)
end
